括号匹配是栈的一个典型应用，给出这道题是希望读者好好掌握栈的应用。算法的基本思想
是扫描每个字符，遇到花、方、圆的左括号时入栈，遇到花、方、圆的右括号时检查栈顶元素是
否为相应的左括号，若是，出栈，否则配对错误。最后栈若不为空也为错误。

```c
bool BracketsCheck(char *str) {
    InitStack(S);            //初始化栈
    int i=0;
    while(str[i]!='\0') {
        switch(str[i]) {
            //左括号入栈
            case '(': Push(S,'('); break;
            case '[': Push(S,'['); break;
            case '{': Push(S,'{'); break;
            //遇到右括号，检测栈顶
            case ')': Pop(S,e);
                if(e!='(') return false;
            break;
            case ']': Pop(S,e);
                if(e!='[') return false;
            break;
            case '}': Pop(S,e);
                if(e!='{') return false;
            break;
            default:
            break;
        }//switch
        i++;
    }//while
    if(!StackEmpty(S)) {
        printf("括号不匹配\n");
        return false;
    }
    else {
        printf("括号匹配\n");
        return true;
    }
}
```

