int visited[MAXSIZE]={0};            //访问标记数组
int BFS(ALGraph G,int i,int j){
//广度优先判断有向图 G 中顶点 $v_i$ 到顶点 $v_j$ 是否有路径，若是，则返回 1，否则返回 0
    InitQueue(Q); EnQueue(Q,i);      //顶点 i 入队
    while(!QueueEmpty(Q)){           //非空循环
        DeQueue(Q,i);                //队头顶点出队
